"""Run every AMD library's cases and tabulate how many kernels Volta tests and finds correct.

    uv run --reinstall-package volta --package volta python external/amd/table.py \
        [-j JOBS] [-o external/amd/table.md] [LIBRARY...]

The cases are `verify.py`'s, grouped by library (PyTorch's activations, not a library's, are
left out), and each runs as `verify.py` runs it: the canonical solver, the graph checks alone,
an expected execution error, or a Lean proof (rechecked from `target/lean/<case>/` while its
challenge is unchanged, else written by Claude Code; `$VOLTA_LEAN_PROJECT` or `.env` gives
the Mathlib project). Only a library's own kernels are counted: a `*_fixed` case is Volta's
fix of a bug, a `*swapped*` case a negative control, and both are listed but not counted.

- Kernels: the library's kernel configurations.
- Tested: those whose run reached the case's expected verdict.
- Correct: those tested and verified (ACCEPT, VERIFIED, or every output proved in Lean).
- Bugs: those tested and rejected as expected (REJECT, REJECTED or ABORT).
"""

import argparse
import sys
import time
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
from enum import Enum
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import verify  # noqa: E402

LIBRARIES = (
    ("Aiter", verify.AITER_ROOT),
    ("AKLR", verify.AKLR_ROOT),
    ("Clblast", verify.OPENCL_ROOT / "clblast"),
    ("Composable Kernels", verify.CK_ROOT),
    ("FlyDSL", verify.FLYDSL_ROOT),
    ("HipKittens", verify.HIPKITTENS_ROOT),
    ("Miopen", verify.OPENCL_ROOT / "miopen"),
    ("Triton AMD", verify.TRITON_ROOT),
)


class Role(Enum):
    UPSTREAM = "upstream"
    FIX = "fix"
    CONTROL = "control"


def role(case: verify.Case) -> Role:
    if case.launch.endswith("_fixed"):
        return Role.FIX
    if "swapped" in case.launch:
        return Role.CONTROL
    return Role.UPSTREAM


def library(case: verify.Case) -> str | None:
    return next((name for name, root in LIBRARIES if case.root == root), None)


@dataclass(frozen=True)
class Result:
    library: str
    case: str
    role: Role
    checker: str
    outcome: verify.Outcome
    seconds: float


def run(index: int) -> tuple[verify.Outcome, float]:
    """Run `verify.CASES[index]` exactly as `verify.py` does, in a worker process."""
    verify.load_dotenv(verify.REPO_ROOT / ".env")
    case = verify.CASES[index]
    kernel = case.root / f"{case.kernel}{case.extension}"
    start = time.monotonic()
    try:
        launch = verify.load_launch(case.root / f"{case.launch}.launch.json")
        if isinstance(case.check, verify.Solve):
            outcome = verify.solve(kernel, launch, case.check, case.sample)
        elif isinstance(case.check, verify.Race):
            outcome = verify.race(kernel, launch, case.check)
        elif isinstance(case.check, verify.Abort):
            outcome = verify.abort(kernel, launch)
        else:
            outcome = verify.prove(case, kernel, launch, case.check)
    except Exception as error:  # noqa: BLE001: a crashed case is untested, not a crashed table
        outcome = verify.Outcome(False, False, f"{type(error).__name__}: {error}")
    return outcome, time.monotonic() - start


@dataclass
class Row:
    kernels: int = 0
    tested: int = 0
    correct: int = 0
    bugs: int = 0
    lean: int = 0

    def add(self, result: Result) -> None:
        self.kernels += 1
        if not result.outcome.expected:
            return
        self.tested += 1
        if result.outcome.verified:
            self.correct += 1
            self.lean += result.checker == "lean"
        else:
            self.bugs += 1


def verdict(result: Result) -> str:
    outcome = result.outcome
    if outcome.verified:
        return "correct"
    return "bug" if outcome.expected else "**not tested**"


def render(results: list[Result], seconds: float) -> str:
    rows = {name: Row() for name, _ in LIBRARIES}
    for result in results:
        if result.role is Role.UPSTREAM:
            rows[result.library].add(result)
    total = Row()
    for row in rows.values():
        for field in ("kernels", "tested", "correct", "bugs", "lean"):
            setattr(total, field, getattr(total, field) + getattr(row, field))

    def line(name: str, row: Row) -> str:
        correct = f"{row.correct}" + (f" ({row.lean} in Lean)" if row.lean else "")
        return f"| {name} | {row.kernels} | {row.tested} | {correct} | {row.bugs} |"

    out = [
        "# AMD HIP kernels",
        "",
        f"Generated by `external/amd/table.py` in {seconds / 60:.1f} min.",
        "",
        "| Library | Kernels | Tested | Correct | Bugs |",
        "|---|---:|---:|---:|---:|",
        *(line(name, rows[name]) for name, _ in LIBRARIES if rows[name].kernels),
        line("**Total**", total),
        "",
        "Kernels: the library's kernel configurations (Volta's `*_fixed` twins and negative "
        "controls excluded). Tested: the run reached its expected verdict. Correct: verified "
        "(ACCEPT, graph checks VERIFIED, or every output proved in Lean). Bugs: rejected as "
        "expected (REJECT, REJECTED or ABORT).",
        "",
        "## Every case",
        "",
        "| Library | Case | Role | Checker | Result | Detail | Time |",
        "|---|---|---|---|---|---|---:|",
    ]
    for r in results:
        detail = r.outcome.detail.replace("|", "\\|").replace("\n", " ")
        out.append(
            f"| {r.library} | `{r.case}` | {r.role.value} | {r.checker} | {verdict(r)} "
            f"| {detail} | {r.seconds:.1f} s |"
        )
    return "\n".join(out) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("libraries", nargs="*", help="only these libraries (default: all)")
    parser.add_argument("-j", "--jobs", type=int, default=1, help="cases run in parallel")
    parser.add_argument(
        "-o", "--output", type=Path, default=Path(__file__).resolve().parent / "table.md"
    )
    args = parser.parse_args()
    known = {name for name, _ in LIBRARIES}
    unknown = set(args.libraries) - known
    if unknown:
        parser.error(f"unknown libraries {sorted(unknown)}; choose from {sorted(known)}")
    wanted = set(args.libraries) or known

    indices = [i for i, case in enumerate(verify.CASES) if library(case) in wanted]
    start = time.monotonic()
    results = []
    with ProcessPoolExecutor(max_workers=args.jobs) as pool:
        for index, (outcome, seconds) in zip(indices, pool.map(run, indices)):
            case = verify.CASES[index]
            result = Result(library(case), case.name(), role(case), case.checker(), outcome, seconds)
            print(
                f"{verdict(result):>14}  {result.library}: {result.case} "
                f"({result.seconds:.1f}s) {result.outcome.detail}",
                flush=True,
            )
            results.append(result)
    args.output.write_text(render(results, time.monotonic() - start), encoding="utf-8")
    print(f"wrote {args.output}", flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())
